import csv
from typing import Dict

def column_means(csv_text: str) -> Dict[str, float]:
    reader = csv.reader(csv_text.splitlines(), quotechar='"')
    header = next(reader)
    data = {col: [] for col in header}

    for row in reader:
        for col, value in zip(header, row):
            if value:
                try:
                    data[col].append(float(value))
                except ValueError:
                    pass

    means = {}
    for col, values in data.items():
        if values:
            means[col] = sum(values) / len(values)

    return means
